# /// script
# requires-python = ">=3.10"
# dependencies = ["wgpu", "numpy"]
# ///
"""Mandelbrot escape times computed on the GPU, then summarized.

Usage: uv run main.py <config-file>
"""

import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 64
MAX_WORKGROUPS_PER_DIM = 65535

SHADER = """
struct Params {
    limit: u32,
    width: u32,
    height: u32,
    stride: u32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read> cxs: array<f32>;
@group(0) @binding(2) var<storage, read> cys: array<f32>;
@group(0) @binding(3) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let idx = gid.x + gid.y * p.stride;
    if (idx >= p.width * p.height) {
        return;
    }
    let cx = cxs[idx % p.width];
    let cy = cys[idx / p.width];
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (!(n < p.limit && zx * zx + zy * zy <= 4.0)) {
            break;
        }
        let nzx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nzx;
        n = n + 1u;
    }
    out[idx] = n;
}
"""


def read_config(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, limit = int(tokens[0]), int(tokens[1]), int(tokens[2])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])
    return width, height, limit, x_min, x_max, y_min, y_max


def escape_times_gpu(width, height, limit, x_min, x_max, y_min, y_max):
    """Return a flat uint32 array of escape times, row-major (row j, column i)."""
    # Grid coordinates are computed in double precision and then narrowed.
    cxs = (x_min + (np.arange(width) + 0.5) * (x_max - x_min) / width).astype(np.float32)
    cys = (y_min + (np.arange(height) + 0.5) * (y_max - y_min) / height).astype(np.float32)
    total = width * height

    groups = -(-total // WORKGROUP_SIZE)
    groups_x = min(groups, MAX_WORKGROUPS_PER_DIM)
    groups_y = -(-groups // groups_x)
    stride = groups_x * WORKGROUP_SIZE

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    params = device.create_buffer_with_data(
        data=np.array([limit, width, height, stride], dtype=np.uint32),
        usage=wgpu.BufferUsage.UNIFORM,
    )
    cx_buf = device.create_buffer_with_data(data=cxs, usage=wgpu.BufferUsage.STORAGE)
    cy_buf = device.create_buffer_with_data(data=cys, usage=wgpu.BufferUsage.STORAGE)
    out_buf = device.create_buffer(
        size=total * 4,
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
            {"binding": 1, "resource": {"buffer": cx_buf, "offset": 0, "size": cx_buf.size}},
            {"binding": 2, "resource": {"buffer": cy_buf, "offset": 0, "size": cy_buf.size}},
            {"binding": 3, "resource": {"buffer": out_buf, "offset": 0, "size": out_buf.size}},
        ],
    )

    encoder = device.create_command_encoder()
    compute_pass = encoder.begin_compute_pass()
    compute_pass.set_pipeline(pipeline)
    compute_pass.set_bind_group(0, bind_group)
    compute_pass.dispatch_workgroups(groups_x, groups_y, 1)
    compute_pass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(out_buf)
    return np.frombuffer(data, dtype=np.uint32, count=total)


def summarize(times, limit):
    inside = times == limit
    escaped = times[~inside].astype(np.int64)

    lines = [f"INSIDE {int(np.count_nonzero(inside))}"]
    # An escaped point has escape time below limit, so its bin is in 0..7.
    bins = (8 * escaped) // limit
    counts = np.bincount(bins, minlength=8)
    for b in range(8):
        lines.append(f"BIN {b} {int(counts[b])}")
    mean = float(escaped.mean()) if escaped.size else 0.0
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main():
    if len(sys.argv) < 2:
        sys.exit("usage: main.py <config-file>")
    width, height, limit, x_min, x_max, y_min, y_max = read_config(sys.argv[1])
    times = escape_times_gpu(width, height, limit, x_min, x_max, y_min, y_max)
    print("\n".join(summarize(times, limit)))


if __name__ == "__main__":
    main()

